INSERT INTO products (name, category, price, mrp, image, description, featured, stock_qty) VALUES
  ('Organic Zing Coffee (Coffea) Oil, 30 ml', 'beauty', 499, NULL, 'https://veehabeauty.com/cdn/shop/files/51DeS9DwLeL._SX679.jpg?v=1743422440', 'Pure, natural coffee (Coffea) oil for skincare, hair care and massage. Dark brown oil with a freshly brewed coffee aroma, in a 30 ml amber glass bottle with dropper. Dilute with a carrier oil before applying and do a patch test first. ASIN: B0CM9HPFRZ.', 1, 100),
  ('AVIMEE Herbal Shakuntala Hair Cleanser, 200 ml', 'beauty', 399, NULL, 'https://media6.ppl-media.com/tr:h-750,w-750,c-at_max,dpr-2,q-40/static/img/product/394962/avimee-herbal-shakuntala-hair-cleanser-for-silky-hair-with-aloe-apple-cider-rice-and-keratin-protein-sls-and-paraben-free-200-ml_1_display_1739259849_a37f1fa8.jpg', 'Herbal daily-use hair cleanser (shampoo) with aloe vera, apple cider vinegar, rice protein and keratin protein. SLS and paraben free. Suitable for men and women. 200 ml. ASIN: B0BNB515G5.', 0, 100),
  ('Radico Colour Me Organic Hair Colour Powder, Soft Black, 100 g', 'beauty', 349, NULL, 'https://ec.nice-cdn.com/upload/image/product/large/default/radico-soft-black-plant-hair-colour-100-g-2089650-en.jpg', 'Herbal hair colour powder in Soft Black, 100 g, made with indigo, henna, amla and bhringraj. Covers grey hair for a natural finish; suitable for men and women. Do a patch test before use and follow the directions on the pack. ASIN: B00DJ53K00.', 0, 100),
  ('Vilvah Milk Face Combo, Brightening Serum 20 ml + Mud Mask 50 g', 'skincare', 799, NULL, 'https://www.vilvahstore.com/cdn/shop/files/M1.jpg?v=1767004381', 'Skincare combo to help de-tan, reduce the look of dark spots and boost glow and hydration: Milk Drops Brightening Serum (20 ml) and Mud Mask (50 g). For all skin types. Do a patch test before first use. ASIN: B0FQJXH17C.', 1, 100),
  ('FACES CANADA Rose Glow Kit, Strobe Cream + Foundation Mini (Caramel Natural)', 'makeup', 799, NULL, 'https://media6.ppl-media.com/tr:h-750,w-750,c-at_max,dpr-2,q-40/static/img/product/393990/faces-canada-rose-glow-kit-5-rose-gold-strobe-cream-30-ml-hydra-matte-foundation-mini-caramel-natural-18-ml-makeup-kit-for-women-combo-pack-of-2_8_display_1745496531_36ce1166.jpg', 'Combo pack of 2 for a glowing, even-looking base: Rose Gold Strobe Cream (30 ml) and All Day Hydra Matte Mini Foundation in Caramel Natural (18 ml). Lightweight, buildable coverage for all skin types. ASIN: B0CXY55VHG.', 1, 100),
  ('HORNBULL Trifold Leather Wallet for Men, Black', 'accessories', 549, NULL, 'images/products/hornbull-trifold-black.jpg', 'Premium top-grain genuine leather trifold wallet in a casual black style. Two compartments and five card slots in a compact, small size. ASIN: B077K2MYMK.', 1, 100),
  ('HORNBULL Steve RFID Blocking Zip-Around Leather Wallet, Brown', 'accessories', 649, NULL, 'https://indusmela.in/cdn/shop/files/71wUpuAYTHL._SL1500.jpg?v=1756364174', 'Brown leather zip-around wallet for men with RFID-blocking protection for your cards. Vertical, slim design with 9 card slots, 1 ID window, 2 money compartments and a zip coin pocket. Medium size. ASIN: B09Q996C69.', 1, 100),
  ('HORNBULL Trifold Genuine Leather Wallet, Green', 'accessories', 549, NULL, 'images/products/hornbull-trifold-green.jpg', 'Genuine leather three-fold wallet in olive green with the HORNBULL logo, RFID protection, ID window and multiple card slots. Slim, compact size for everyday use. ASIN: B09QPVPPJT.', 0, 100),
  ('WILDHORN Hand-Crafted Bifold Leather Wallet, WH1173 (Style 1)', 'accessories', 499, NULL, 'https://m.media-amazon.com/images/I/71s4oSgHvMS.jpg', 'Hand-crafted bifold wallet for men in genuine leather with a flap closure and multiple card and note sections. Model WH1173. Compact size, about 150 g. ASIN: B08P5ML6GK.', 1, 100),
  ('WILDHORN Hand-Crafted Bifold Leather Wallet, WH1173 (Style 2)', 'accessories', 499, NULL, 'https://rukminim2.flixcart.com/image/480/640/k5ihzm80/accessories-combo/j/v/f/wh2052combo-wildhorn-original-imafz6j2n98dgbd4.jpeg', 'Hand-crafted bifold wallet for men in genuine leather. Model WH1173, a second colour option. Compact size, about 150 g. ASIN: B08P5M592H.', 0, 100),
  ('URBAN FOREST Oliver Aniline Black Leather Wallet', 'accessories', 499, NULL, 'https://m.media-amazon.com/images/I/51ILZhcnWCL._SL500_.jpg', 'Contemporary black wallet for men in genuine aniline leather with easy-access card slots, for cards and cash. Compact design. ASIN: B0C2C2TRL8.', 1, 100);
